<?php require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="mb-1">Inventory overview</h2><p class="text-muted">Monitor your collection and circulation activity.</p></div><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=books&action=create">+ Add book</a></div><div class="row g-3 mb-4"><?php foreach([['Books',$stats['books']],['Available copies',$stats['available']],['Checked out',$stats['borrowed']],['Overdue',$stats['overdue']]] as $s):?><div class="col-md-3"><div class="card stat"><span class="text-muted"><?= $s[0] ?></span><div class="value"><?= $s[1] ?></div></div></div><?php endforeach;?></div><div class="card p-3"><h5>Recent activity</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Book</th><th>User</th><th>Action</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?= App\Core\Security::e($r['title']) ?></td><td><?= App\Core\Security::e($r['user_name']) ?></td><td><?= App\Core\Security::e(ucwords(str_replace('_',' ',$r['status']))) ?></td><td><?= App\Core\Security::e($r['checked_out_at']) ?></td></tr><?php endforeach;?></tbody></table></div></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
